15	// ContextExistsMsg reports whether the named context already has a file on
16	// disk.
17	type ContextExistsMsg struct {
18		Exists bool
19		Err    error
20	}
21	
22	func checkContextExistsCmd(name string) tea.Cmd {
23		return func() tea.Msg {
24			exists, err := config.ContextExists(name)
25			return ContextExistsMsg{Exists: exists, Err: err}
26		}
27	}
