29	// TokenValidatedMsg reports the outcome of authenticating the forge token the
30	// user typed. A nil Err means the token itself is valid; SaveWarning is set
31	// whenever it did not actually end up somewhere durable — either because
32	// Authenticate's own write failed, or because Select had already resolved to
33	// memory-only storage. A token that "validates" but is never asked about
34	// again — this used to be silent, which is exactly what sent a user back to
35	// a logged-out app after being told setup succeeded.
36	type TokenValidatedMsg struct {
37		Err         error
38		SaveWarning string
39	}
40	
41	func validateTokenCmd(contextName, secretBackend, forgeType, url, token string) tea.Cmd {
42		return func() tea.Msg {
43			sel := credentials.Select(contextName, secretBackend)
44			result, err := session.NewAuth(sel.Storage).Authenticate(context.Background(), forgeType, url, token)
45			if err != nil {
46				return TokenValidatedMsg{Err: err}
47			}
48			warning := result.SaveWarning
49			if warning == "" && !sel.Persists() {
50				warning = sel.Detail
51			}
52			return TokenValidatedMsg{SaveWarning: warning}
53		}
54	}
