56	// SecretBackendCheckedMsg reports whether a candidate secret backend
57	// actually resolves to somewhere durable right now — the same question
58	// credentials.Select answers, surfaced before the user has typed a token
59	// into it rather than only after (Rule: detect this as early as possible).
60	type SecretBackendCheckedMsg struct {
61		Persists bool
62		Detail   string
63	}
64	
65	func checkSecretBackendCmd(contextName, preference string) tea.Cmd {
66		return func() tea.Msg {
67			sel := credentials.Select(contextName, preference)
68			return SecretBackendCheckedMsg{Persists: sel.Persists(), Detail: sel.Detail}
69		}
70	}
