72	// ContainerEngineCheckedMsg reports whether a candidate container engine is
73	// not just installed but actually running. Missing means no binary was found
74	// at all; Err means the binary exists but its daemon did not answer — the
75	// distinction the app's own tool detection does not make today (it only
76	// checks the client, which answers even with the daemon down).
77	type ContainerEngineCheckedMsg struct {
78		Missing bool
79		Err     error
80		Name    string
81	}
82	
83	func checkContainerEngineCmd(preference string) tea.Cmd {
84		return func() tea.Msg {
85			shape, err := engine.Resolve(preference)
86			if err != nil {
87				return ContainerEngineCheckedMsg{Missing: true}
88			}
89			// Safe to mutate: this is a separate, short-lived process from the
90			// real `dk`, which re-resolves its own engine.Current() fresh at
91			// startup (app.resolveContainerEngine) — nothing here leaks into it.
92			engine.SetCurrent(shape)
93			if _, err := docker.FetchCapacity(); err != nil {
94				return ContainerEngineCheckedMsg{Err: err, Name: shape.Name}
95			}
96			return ContainerEngineCheckedMsg{Name: shape.Name}
97		}
98	}
