19	func TestKeyringStorageRoundTrip(t *testing.T) {
20		mockKeyring(t)
21		storage := NewKeyringStorage("default")
22	
23		if err := storage.Save("https://gitlab.example.com", "glpat-secret"); err != nil {
24			t.Fatalf("Save() error = %v", err)
25		}
26	
27		got, err := storage.Load("https://gitlab.example.com")
28		if err != nil {
29			t.Fatalf("Load() error = %v", err)
30		}
31		if got != "glpat-secret" {
32			t.Errorf("Load() = %q, want glpat-secret", got)
33		}
34	
35		if err := storage.Delete("https://gitlab.example.com"); err != nil {
36			t.Fatalf("Delete() error = %v", err)
37		}
38		if _, err := storage.Load("https://gitlab.example.com"); err == nil {
39			t.Error("Load() after Delete returned no error")
40		}
41	}
