54		}
55		if err := personal.Save(url, "personal-token"); err != nil {
56			t.Fatalf("personal Save() error = %v", err)
57		}
58	
59		got, err := work.Load(url)
60		if err != nil {
61			t.Fatalf("work Load() error = %v", err)
62		}
63		if got != "work-token" {
64			t.Errorf("work Load() = %q, want work-token — the personal context overwrote it", got)
65		}
